<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {ApiError,onIdentityChange} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {useResource} from '@/core/use-resource'
import AsyncState from '@/ui/AsyncState.vue'
import {typeDeviceUuid} from '../device-types/type-devices-api'
import type {OtaFirmware} from './ota-read-api'
import {otaManagementTransport,otaMetadataDraft,prepareOtaMetadata,prepareOtaMetadataIntent,decodeOtaMetadataRequest,type OtaManagementTransport,type OtaMetadataIntent} from './ota-management-metadata-api'
import {otaFirmwareManagementTransport,otaTargetDraft,prepareOtaTargetConditions,prepareOtaFirmwareManagementIntent,decodeOtaFirmwareManagementResult,type OtaFirmwareManagementTransport,type OtaFirmwareManagementIntent,type OtaFirmwareManagementView} from './ota-target-conditions-api'
import MetadataFields from './OtaFirmwareMetadataFields.vue'
import TargetFields from './OtaFirmwareTargetFields.vue'
const props=withDefaults(defineProps<{firmware?:OtaFirmware;firmwareId?:string;disabled?:boolean;portal?:boolean;overviewTarget?:HTMLElement|null;settingsTarget?:HTMLElement|null;editLabel?:string;transport?:OtaFirmwareManagementTransport;notesTransport?:OtaManagementTransport}>(),{editLabel:'编辑版本资料',transport:()=>otaFirmwareManagementTransport,notesTransport:()=>otaManagementTransport})
const emit=defineEmits<{locked:[value:boolean];changed:[]}>()
const id=computed(()=>props.firmwareId||props.firmware?.id||'')
const readable=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&typeDeviceUuid.test(projectId.value)&&typeDeviceUuid.test(id.value)&&(!props.firmware||props.firmware.projectId===projectId.value)&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||'')&&can('ota:read'))
const writable=computed(()=>readable.value&&currentProject.value?.status==='ACTIVE'&&can('ota:deploy')&&!props.disabled)
const metadata=useResource(signal=>props.notesTransport.read(projectId.value,id.value,signal)),targetHead=useResource(signal=>props.transport.target(projectId.value,id.value,signal))
const editing=ref(false),mode=ref<'management'|'notes'>('management'),draft=ref(otaMetadataDraft()),targets=ref(otaTargetDraft()),targetsInitialized=ref(false),busy=ref(false),unknown=ref(false),conflict=ref(false),error=ref(''),message=ref('')
type Intent=Readonly<{kind:'management';value:OtaFirmwareManagementIntent}>|Readonly<{kind:'notes';value:OtaMetadataIntent}>
let intent:Intent|undefined,generation=0,alive=true,write:AbortController|undefined
const frozen=computed(()=>busy.value||unknown.value),ready=computed(()=>{if(!writable.value||frozen.value||conflict.value||!metadata.data.value)return false;try{prepareOtaMetadata(draft.value);if(mode.value==='management'){if(!targetHead.data.value||!targetsInitialized.value)return false;prepareOtaTargetConditions(targets.value)}else if(metadata.data.value.metadata.metadata===null)return false;return true}catch{return false}})
watch(frozen,value=>emit('locked',value),{immediate:true,flush:'sync'})
function current(g:number){return alive&&g===generation&&readable.value}
function view():OtaFirmwareManagementView{if(!metadata.data.value||!targetHead.data.value)throw new Error('请先读取当前版本资料和目标条件');return {...metadata.data.value,targetConditions:{targetConditions:targetHead.data.value.targetConditions,revision:targetHead.data.value.revision}}}
function seed(){if(metadata.data.value)draft.value=otaMetadataDraft(metadata.data.value.metadata);if(targetHead.data.value){targets.value=otaTargetDraft(targetHead.data.value.targetConditions);targetsInitialized.value=true}else targetsInitialized.value=false}
async function readCurrent(includeTargets:boolean){metadata.clear();if(includeTargets)targetHead.clear();await Promise.all([metadata.reload(),...(includeTargets?[targetHead.reload()]:[])])}
function reset(){generation++;write?.abort();metadata.clear();targetHead.clear();editing.value=false;busy.value=false;unknown.value=false;conflict.value=false;draft.value=otaMetadataDraft();targets.value=otaTargetDraft();targetsInitialized.value=false;intent=undefined;error.value='';message.value='';if(readable.value){void metadata.reload();void targetHead.reload()}}
async function reload(){if(!readable.value||frozen.value)return;const g=generation;await readCurrent(mode.value==='management');if(current(g)){seed();conflict.value=false;error.value=''}}
async function reloadMetadata(){if(!readable.value||frozen.value)return;metadata.clear();await metadata.reload()}
async function reloadTargets(){if(!readable.value||frozen.value)return;targetsInitialized.value=false;targetHead.clear();await targetHead.reload()}
watch(targetHead.data,value=>{if(value&&editing.value&&mode.value==='management'&&!targetsInitialized.value&&!frozen.value){targets.value=otaTargetDraft(value.targetConditions);targetsInitialized.value=true}})
function edit(){if(!writable.value||frozen.value||!metadata.data.value)return;mode.value='management';seed();editing.value=true;conflict.value=false;error.value='';message.value='';if(!targetHead.data.value&&!targetHead.loading.value)void reloadTargets()}
function editNotes(){if(!writable.value||frozen.value||!metadata.data.value)return;if(metadata.data.value.metadata.metadata===null){edit();message.value='该历史版本尚未设置名称，请先补充版本资料。';return}mode.value='notes';draft.value=otaMetadataDraft(metadata.data.value.metadata);editing.value=true;conflict.value=false;error.value='';message.value=''}
function cancel(){if(frozen.value)return;editing.value=false;conflict.value=false;error.value='';intent=undefined}
function updateEditing(value:boolean){if(!value)cancel()}
function beforeClose(done:()=>void){if(!frozen.value){cancel();done()}}
async function complete(result:unknown,g:number){if(!current(g)||!intent)return;const kind=intent.kind;if(intent.kind==='management')decodeOtaFirmwareManagementResult(result,intent.value);else decodeOtaMetadataRequest(result,intent.value);unknown.value=false;editing.value=false;intent=undefined;message.value=kind==='notes'?'版本说明和标签已保存':'版本资料已保存';await readCurrent(kind==='management');if(current(g)){emit('changed');if(kind==='notes'&&!targetHead.data.value&&!targetHead.error.value&&!targetHead.loading.value)void targetHead.reload()}}
async function save(){if(!ready.value||!metadata.data.value)return;const g=generation;if(mode.value==='management')intent=Object.freeze({kind:'management',value:prepareOtaFirmwareManagementIntent(projectId.value,id.value,view(),draft.value,targets.value)});else{const originalName=metadata.data.value.metadata.metadata?.name;if(originalName===undefined)return;intent=Object.freeze({kind:'notes',value:prepareOtaMetadataIntent(projectId.value,id.value,metadata.data.value.metadata,{...draft.value,name:originalName})})}write=new AbortController();busy.value=true;unknown.value=true;error.value='';try{const result=intent.kind==='management'?await props.transport.update(intent.value,write.signal):await props.notesTransport.update(intent.value,write.signal);await complete(result,g)}catch(cause){if(!current(g))return;unknown.value=!(cause instanceof ApiError)||cause.outcomeUnknown||cause.code===10010||cause.code===10014;conflict.value=cause instanceof ApiError&&cause.status===409&&!unknown.value;error.value=unknown.value?'保存结果尚未核实，请读取原保存结果；不会重复提交。':conflict.value?'版本资料已更新，请读取最新资料后再编辑。':cause instanceof Error?cause.message:'保存失败'}finally{if(alive&&g===generation)busy.value=false}}
async function recover(){if(!readable.value||busy.value||!unknown.value||!intent)return;const g=generation;write=new AbortController();busy.value=true;error.value='';try{const result=intent.kind==='management'?await props.transport.recover(intent.value,write.signal):await props.notesTransport.recover(intent.value,write.signal);await complete(result,g)}catch(cause){if(current(g))error.value=cause instanceof ApiError&&cause.status===404?'原保存结果尚未可读，请稍后继续核对。':cause instanceof Error?cause.message:'读取失败'}finally{if(alive&&g===generation)busy.value=false}}
watch([()=>projectId.value,id,()=>session.user?.accountId,()=>props.transport,()=>props.notesTransport],reset,{immediate:true,flush:'sync'})
watch(readable,value=>{metadata.clear();targetHead.clear();if(!value){generation++;write?.abort();busy.value=false;if(!unknown.value)cancel();return}if(!unknown.value){void metadata.reload();void targetHead.reload()}},{flush:'sync'})
const dispose=onIdentityChange(reset)
onScopeDispose(()=>{alive=false;generation++;write?.abort();dispose();emit('locked',false)})
defineExpose({edit,editNotes})
</script>
<template><Teleport :to="overviewTarget||'body'" :disabled="!overviewTarget"><section v-if="readable&&(!portal||overviewTarget)" class="ota-management"><header><h3>版本资料</h3><el-button v-if="writable" size="small" :disabled="metadata.loading.value||frozen||!metadata.data.value" @click="edit">{{editLabel}}</el-button></header><AsyncState :loading="metadata.loading.value" :error="metadata.error.value" @retry="reloadMetadata"><dl v-if="metadata.data.value"><dt>版本名称</dt><dd>{{metadata.data.value.metadata.metadata?.name??'未设置'}}</dd></dl></AsyncState><AsyncState :loading="targetHead.loading.value" :error="targetHead.error.value" @retry="reloadTargets"><dl v-if="targetHead.data.value"><dt>待升级设备</dt><dd><template v-if="targetHead.data.value.targetConditions.deviceIds!==null">已指定 {{targetHead.data.value.targetConditions.deviceIds.length}} 台设备<details><summary>查看指定设备</summary><ul><li v-for="device in targetHead.data.value.targetConditions.deviceIds" :key="device">{{device}}</li></ul></details></template><span v-else>所属类型全部设备</span></dd><dt>待升级版本</dt><dd class="description">{{targetHead.data.value.targetConditions.sourceFirmwareVersion??'不限设备当前版本'}}</dd></dl></AsyncState></section></Teleport>
<Teleport :to="settingsTarget||'body'" :disabled="!settingsTarget"><section v-if="readable&&(!portal||settingsTarget)" class="ota-management"><header><h3>版本说明和标签</h3><el-button v-if="writable" size="small" :disabled="metadata.loading.value||frozen||!metadata.data.value" @click="editNotes">{{metadata.data.value?.metadata.metadata?'编辑说明和标签':'补充版本资料'}}</el-button></header><AsyncState :loading="metadata.loading.value" :error="metadata.error.value" @retry="reloadMetadata"><template v-if="metadata.data.value"><p v-if="metadata.data.value.metadata.metadata===null" class="help">历史版本尚未设置名称、说明和标签，可先补充版本资料。</p><dl v-else><dt>版本说明</dt><dd class="description">{{metadata.data.value.metadata.metadata.description??'未设置'}}</dd><dt>标签</dt><dd><template v-if="Object.keys(metadata.data.value.metadata.metadata.tags).length"><el-tag v-for="(value,key) in metadata.data.value.metadata.metadata.tags" :key="key">{{key}}：{{value}}</el-tag></template><span v-else>未设置</span></dd></dl></template></AsyncState></section></Teleport>
<p v-if="message&&readable" role="status" class="ota-metadata-message">{{message}}</p><p v-if="unknown&&!readable" role="alert">保存结果仍待核对，恢复版本资料读取权限后可继续读取原结果。</p><el-dialog v-if="readable" :model-value="editing" :title="mode==='notes'?'编辑说明和标签':'编辑版本资料'" width="min(600px,96vw)" :close-on-click-modal="false" :close-on-press-escape="!frozen" :show-close="!frozen" :before-close="beforeClose" @update:model-value="updateEditing"><el-form label-position="top"><template v-if="mode==='management'"><MetadataFields v-model="draft" section="name" :disabled="frozen||!writable"/><AsyncState :loading="targetHead.loading.value" :error="targetHead.error.value" @retry="reloadTargets"><TargetFields v-if="metadata.data.value&&targetsInitialized" v-model="targets" :device-type-id="metadata.data.value.firmware.deviceTypeId" :disabled="frozen||!writable" :loader="transport.devices"/></AsyncState><MetadataFields v-model="draft" section="description" :disabled="frozen||!writable"/></template><MetadataFields v-else v-model="draft" section="details" :disabled="frozen||!writable"/></el-form><p v-if="error" role="alert">{{error}}</p><p v-if="unknown" class="help">原保存请求：{{intent?.value.key}}</p><template #footer><el-button :disabled="frozen" @click="cancel">取消</el-button><el-button v-if="conflict" :disabled="frozen" @click="reload">读取最新资料</el-button><el-button v-if="unknown" :loading="busy" @click="recover">读取原保存结果</el-button><el-button v-else type="primary" :disabled="!ready" :loading="busy" @click="save">{{mode==='notes'?'保存说明和标签':'保存版本资料'}}</el-button></template></el-dialog></template>
<style scoped>.ota-management{margin-bottom:24px}.ota-management header{display:flex;align-items:center;justify-content:space-between;gap:12px}.ota-management h3{font-size:17px;font-weight:500}.ota-management dl{display:grid;grid-template-columns:100px minmax(0,1fr);gap:12px;font-size:13px}.ota-management dt,.help{color:var(--tl-muted)}.ota-management dd{margin:0;overflow-wrap:anywhere}.description{white-space:pre-wrap}.ota-management .el-tag{margin:0 8px 6px 0}.help,.ota-metadata-message{font-size:12px;line-height:20px;overflow-wrap:anywhere}[role=alert]{color:var(--el-color-danger)}</style>
